raw:
SELECT AVG((CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', '%Y-%m-%d', Birthday) AS INTEGER))) AS average_age
FROM Patient
WHERE SEX = 'M' AND (SELECT T-CHO FROM Laboratory WHERE Laboratory.ID = Patient.ID) >= 250;

sql:
SELECT AVG((CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', '%Y-%m-%d', Birthday) AS INTEGER))) AS average_age
FROM Patient
WHERE SEX = 'M' AND (SELECT T-CHO FROM Laboratory WHERE Laboratory.ID = Patient.ID) >= 250;

